landscape_ui <- function(d) {
  library(shiny)
  if(is.null(d$landcover)) return(div(id='page-landscape',class='atlas-page',hidden=NA,
    h2('Explore landscape change'),p('Land-cover data are currently unavailable.')))
  e<-d$landcover$epochs;c<-d$landcover$classes
  div(id='page-landscape',class='atlas-page',hidden=NA,
    div(class='context-line','Victoria',span('Historical periods: 1985–2019'),span('Mapped land cover')),
    div(class='landscape-intro',h2('How has the land changed over time?'),
      p('Choose a cover type, such as trees, crops or water, and two historical periods. Compare how much of each area was mapped as that cover type, and whether its share increased or decreased.'),
      p(class='caption','These historical maps end in 2019. They describe land cover, not management rankings. A change in cover alone does not establish its cause or whether the environment improved.')),
    div(class='landscape-controls',
      div(class='unit-search',selectizeInput('land_area','1. Find an area',choices=setNames(d$areas$microID,d$areas$Name),selected='unit668',options=list(placeholder='Search a unit number',maxOptions=nrow(d$areas),openOnFocus=FALSE,onInitialize=I("function() { this.$control_input.attr('autocomplete', 'off'); this.$control.addClass('unit-search-control'); }"),onDropdownOpen=I("function() { if (!this.$control_input.val().trim()) this.close(); }"))),p(class='caption unit-search-hint',paste('Units are mapped areas. Search all',number(nrow(d$areas)),'by number, or click the map.'))),
      selectInput('land_class','2. Choose a cover type',choices=setNames(c$class_code,c$class_label),selected=12),
      selectInput('start_epoch','3. Earlier period',choices=setNames(head(e$epoch_id,-1),head(e$epoch_label,-1)),selected=e$epoch_id[1]),
      selectInput('end_epoch','4. Later period',choices=setNames(e$epoch_id[-1],e$epoch_label[-1]),selected=tail(e$epoch_id,1))),
    p(class='caption period-help','Each period covers several years. Earlier and later periods control the comparisons; the history chart always shows all seven periods.'),
    div(class='workspace landscape-workspace',
      tags$aside(class='control-rail',`aria-label`='Landscape controls',
        selectInput('land_metric','What should the map show?',choices=c('Cover in the later period (%)'='share','Change between periods'='change'),selected='change'),
        p(class='caption','Use cover to compare areas at one time, or change to compare the two periods.'),
        actionButton('land_zoom','Zoom to selected area',class='button-outline'),
        checkboxInput('land_context','Show place labels online',FALSE),
        actionButton('land_pin','Pin this area',class='button-primary'),
        div(class='pin-section',h3('Pinned areas'),uiOutput('land_pinned')),
        actionButton('land_clear','Clear comparison',class='button-outline'),
        downloadButton('download_landcover','Download selected areas',class='button-dark'),
        p(class='rail-note','Pin up to three areas to compare. Your selected area and pins are shared with Explore priorities.')),
      div(class='map-region',
        h3(class='land-map-heading',textOutput('land_map_title',inline=TRUE)),
        p(class='caption','Each shape summarises a whole area. Hover to read its value; click to select it.'),
        leaflet::leafletOutput('landcover_map',height='520px'),
        div(class='map-caption',textOutput('land_map_caption'),span('Solid outline: selected · dashed outline: pinned'))),
      tags$aside(class='detail-rail',`aria-label`='Selected-area land cover',uiOutput('land_focus'))),
    tags$section(class='land-change-section',
      div(class='section-heading',h2('Which cover types increased or decreased?'),
        radioButtons('change_unit','Show change as',choices=c('Percentage points'='pp','Hectares'='ha'),inline=TRUE)),
      p(class='caption','This chart shows all 19 cover types in the selected area. Right / green means an increase; left / brown means a decrease. Colour shows direction, not environmental benefit or harm. These totals do not identify what one cover type replaced.'),
      plotOutput('class_changes',height='590px')),
    tags$section(class='land-comparison-section',
      div(class='section-heading',h2('Compare this cover type across areas'),p('Each row is your selected area or a pinned area. Read its earlier and later percentages, then the difference. Overlapping areas are kept separate.')),
      p(class='caption','Percentage points mean later percentage minus earlier percentage. For example, 30% to 35% is an increase of 5 percentage points. Hectares describe the change in mapped area.'),
      uiOutput('land_comparison')),
    tags$details(id='local-evidence',open=if(!tableau_config()$valid) NA else NULL,
      tags$summary('Follow this cover type through all seven periods'),
      p(class='caption','Each coloured line represents one selected or pinned area. Each point shows the percentage of classified land mapped as your chosen cover type. All seven periods remain visible, whatever earlier and later periods you choose above.'),
      plotOutput('land_trends',height='330px'),
      h3(class='exact-values-heading','Exact values for all cover types'),
      p(class='caption','The table compares your chosen earlier and later periods. The download includes all seven periods.'),
      div(class='evidence-scroll',uiOutput('land_values'))),
    tags$details(class='method-note',tags$summary('How percentages and hectares are calculated'),
      p('Percentages use land that the source could classify within each area and period. Unclassified land (code 0) and missing coverage are excluded from the denominator and reported separately. Hectares are projected grid areas in EPSG:3111. Units can overlap, so their hectares must not be added into a statewide total.'),
      p('The earliest downloaded period is labelled 1985-1990; the catalogue describes it as 1987-1990. The app follows the downloaded files.')),
    tags$section(class='tableau-section',h2('Explore composition and trends in Tableau'),
      p('Stacked bars show how the cover types make up an area in each period. In the workbook, set Chart 1: what should the bars show? to Selected cover type, then choose a Cover type to see even small categories on an adjusted percentage scale. Lines follow one cover type through time. Start/end dots compare its percentage in your two chosen periods.'),uiOutput('tableau')))
}
